sampler sampler_pw_noise_lq;

float2 rs, rss, rss0, tmp, uvo;
float3 noise;

float2 complex_div(float2 numerator, float2 denominator){
   return float2( numerator.x*denominator.x + numerator.y*denominator.y,
                  numerator.y*denominator.x - numerator.x*denominator.y)/
          (denominator.x*denominator.x + denominator.y*denominator.y);
}

float2 uv_polar(float2 domain, float2 center){
   float2 c = domain - center;
   float rad_hq = length(c);
   float ang_hq = atan2(c.x,c.y);
   return float2(ang_hq, rad_hq);
}

float2 uv_polar_logarithmic(float2 domain, float2 center, int fins, float log_factor, float2 coord){
   float2 polar = uv_polar(domain, center);
   return float2(polar.x*fins+coord.x, log_factor*log(polar.y) + coord.y);
}

float2 uv_moebius_transformation(float2 domain, float2 zeroPoint, float2 infinityPoint,float zoom){
   return complex_div((domain - zeroPoint)*zoom, domain - infinityPoint)+0.5;
}

float2 uv_bipolar_logarithmic(float2 domain, float2 northPole, float2 southPole, int fins, float log_factor, float2 coord){
   float2 help_uv = uv_moebius_transformation(domain, northPole, southPole, 1);
   return uv_polar_logarithmic(help_uv,0.5,fins,log_factor,coord)*float2(M_INV_PI_2,1);
}

float2 uv_scale(float2 domain, float2 center, float2 scale){
   return center + (domain-center)*scale;
}
float2 uv_lens_half_sphere(float2 domain, float2 position, float radius, float refractivity){
   float2 polar = uv_polar(domain, position);
   float cone = saturate(1-polar.y/radius);
   float halfsphere = sqrt(1-pow(cone-1,2));
   float w = atan2(1-cone,halfsphere);
   float refrac_w = w-asin(sin(w)/refractivity);
   float refrac_d = 1-cone - sin(refrac_w)*halfsphere/cos(refrac_w);
   float2 refrac_uv =position+float2(sin(polar.x),cos(polar.x))*refrac_d*radius;
   bool mask =(length(domain-position)<radius);
   return !mask*domain + 
           mask*refrac_uv;
}

/* code from Martins hardcore mix - Danke ;) */
float hardcore_stars(float2 domain, float2 center, float o){

   float2 uv1 = domain-center;
   rss0.x = atan2(uv1.x, uv1.y)/3.1416;
   rss0.y = .003/(length (uv1));
   rss = float2 (rss0.x+q1/3,rss0.y+time+o);
   rss = mul(rss,float2x2(.7,.7,-.7,.7));
   float noise = (tex2D(sampler_pw_noise_lq,rss/32)-.5 >= 0);
   tmp = abs(frac(rss*8)-.5);
   float3 dots = saturate(.04/length(tmp)) *noise;
   rss = float2 (rss0.x,rss0.y+(time+o)/4);
   rss = mul(rss,float2x2(.7,.7,-.7,.7));
   noise = (tex2D(sampler_pw_noise_lq,rss/32)-.5 >= 0);
   tmp = abs(frac(rss*8)-.5);
   dots += saturate(.02/length(tmp)) * noise;
   dots *= saturate(.2/abs(rss0.y));
   return dots*dots;
return 0;
}






